const queue = this.getInputData(0).json.queue;
const visited = this.getInputData(0).json.visited;
const processedResults = this.getInputData(0).json.processed_results;

let nextItem = null;
let originalQueue = [...queue]; // 复制一份，以便稍后更新

if (queue.length > 0) {
  nextItem = originalQueue.shift(); // 取出第一个
}

if (nextItem && !visited.includes(nextItem.id)) {
  // 如果未访问过，则加入已访问列表，并准备处理
  visited.push(nextItem.id);
  return [
    {
      json: {
        current_item: nextItem,
        queue: originalQueue,
        visited: visited,
        processed_results: processedResults,
        should_process: true // 标记为需要处理
      }
    }
  ];
} else {
  // 如果已访问或队列为空，则不进行处理，只更新队列和访问列表
  return [
    {
      json: {
        current_item: null, // 没有要处理的项
        queue: originalQueue,
        visited: visited,
        processed_results: processedResults,
        should_process: false // 标记为不需要处理
      }
    }
  ];
}

const inputData = this.getInputData(0);
const currentItem = inputData.json.current_item;
const queue = inputData.json.queue;
const visited = inputData.json.visited;
const processedResults = inputData.json.processed_results;

const allData = [
  {
    "id": "post-a",
    "title": "文章 A",
    "links": ["post-b", "post-c"]
  },
  {
    "id": "post-b",
    "title": "文章 B",
    "links": ["post-d"]
  },
  {
    "id": "post-c",
    "title": "文章 C",
    "links": ["post-a", "post-e"]
  },
  {
    "id": "post-d",
    "title": "文章 D",
    "links": []
  },
  {
    "id": "post-e",
    "title": "文章 E",
    "links": []
  }
];

const foundItem = allData.find(item => item.id === currentItem.id);

if (foundItem) {
  // 添加深度信息并返回所有必要数据
  foundItem.depth = currentItem.depth;
  return [
    {
      json: {
        current_item_data: foundItem,
        queue: queue,
        visited: visited,
        processed_results: processedResults
      }
    }
  ];
} else {
  // 如果找不到，返回空数据但保留状态
  return [
    {
      json: {
        current_item_data: null,
        queue: queue,
        visited: visited,
        processed_results: processedResults
      }
    }
  ];
}

// 获取输入数据
const inputData = this.getInputData(0);
const currentItemData = inputData.json.current_item_data;
const queue = [...inputData.json.queue]; // 创建副本以避免修改原数组
const visited = [...inputData.json.visited];
const processedResults = [...inputData.json.processed_results];

const MAX_DEPTH = 2; // 设置最大深度以避免无限递归

if (currentItemData) {
  // 将当前处理的项加入结果列表
  processedResults.push({
    id: currentItemData.id,
    title: currentItemData.title,
    depth: currentItemData.depth
  });

  // 如果未达到最大深度，则处理其子链接
  if (currentItemData.depth < MAX_DEPTH && currentItemData.links && currentItemData.links.length > 0) {
    currentItemData.links.forEach(linkId => {
      // 只有当子链接未被访问过时才加入队列
      if (!visited.includes(linkId)) {
        queue.push({
          id: linkId,
          depth: currentItemData.depth + 1
        });
      }
    });
  }
}

// 返回更新后的所有状态
return [
  {
    json: {
      queue: queue,
      visited: visited,
      processed_results: processedResults
    }
  }
];

// 当不需要处理时，直接传递状态数据
const inputData = this.getInputData(0);
return [
  {
    json: {
      queue: inputData.json.queue,
      visited: inputData.json.visited,
      processed_results: inputData.json.processed_results
    }
  }
];
